window.__census = async (name, detail) => {
  const app = window.__CITY_APP, r = app.renderer;
  const sleep = (ms) => new Promise((res) => setTimeout(res, ms));
  await sleep(2500);
  app.cpuTimes && app.cpuTimes();
  app.gpuTimes && app.gpuTimes();
  const d = []; let last = performance.now(); const t = last;
  await new Promise((res) => { (function f(now) { d.push(now - last); last = now; if (now - t < 4000) requestAnimationFrame(f); else res(); })(t); });
  d.shift(); d.sort((a, b) => a - b);
  const mean = d.reduce((a, b) => a + b, 0) / d.length;
  const cpu = app.cpuTimes ? app.cpuTimes() : null;
  const gpu = app.gpuTimes ? app.gpuTimes() : null;
  // one rendered frame's draws
  const orig = r._renderObjectDirect;
  const byRoot = new Map(), byMat = new Map(), byPass = new Map(), byObj = new Map();
  let n = 0, objs = 0;
  const add = (m, k, tri) => { const e = m.get(k) || [0, 0]; e[0]++; e[1] += tri; m.set(k, e); };
  r._renderObjectDirect = function (object, material, scene, camera) {
    n++;
    const pass = camera.isOrthographicCamera ? 'shadow' : (scene.name || scene.type) + '/' + (camera.name || camera.type);
    let o = object, chain = [];
    while (o.parent && o.parent !== scene) { chain.push(o.parent.name || o.parent.type); o = o.parent; }
    const root = (o.name || o.type);
    const sub = chain.length >= 2 ? chain[chain.length - 2] : (object.name || object.type);
    const g = object.geometry; const tri = g ? ((g.index ? g.index.count : (g.attributes.position ? g.attributes.position.count : 0)) / 3) * (object.isInstancedMesh ? object.count : 1) : 0;
    add(byPass, pass, tri);
    add(byRoot, pass[0] + ' ' + root + ' > ' + sub, tri);
    add(byMat, pass[0] + ' ' + root + ' | ' + (material.name || material.type), tri);
    if (detail) add(byObj, pass[0] + ' ' + root + ' > ' + (object.name || object.type) + (object.isInstancedMesh ? '[i' + object.count + ']' : ''), tri);
    return orig.apply(this, arguments);
  };
  const f0 = app.frameNo;
  while (app.frameNo < f0 + 2) await new Promise((res) => requestAnimationFrame(res));
  const f1 = app.frameNo; n = 0; byRoot.clear(); byMat.clear(); byPass.clear(); byObj.clear();
  while (app.frameNo < f1 + 1) await new Promise((res) => requestAnimationFrame(res));
  delete r._renderObjectDirect;
  let sceneObjs = 0, vis = 0; app.scene.traverseVisible(() => vis++); app.scene.traverse(() => sceneObjs++);
  const top = (m, k) => [...m].sort((a, b) => b[1][0] - a[1][0]).slice(0, k).map(([key, [c, tr]]) => `${c}\t${Math.round(tr / 1000)}k\t${key}`).join('\n');
  const info = r.info.render;
  console.log(`[census] ${name} mean ${mean.toFixed(1)} ms p50 ${d[d.length >> 1].toFixed(1)} p90 ${d[Math.floor(d.length * 0.9)].toFixed(1)} | tier ${CITY.QUALITY.tier} | draws(handled) ${n} info.drawCalls ${info.drawCalls} tris ${info.triangles} | cpu ${JSON.stringify(cpu)} | gpu ${gpu ? JSON.stringify({ frames: gpu.frames, render: gpu.render, top: Object.entries(gpu.passes).slice(0, 6) }) : '-'} | objects ${sceneObjs} visibleWalk ${vis}`);
  console.log(`[census] ${name} cullingStats ${JSON.stringify(app.cullingStats)}`);
  console.log(`[census] ${name} PASSES\n${top(byPass, 20)}`);
  console.log(`[census] ${name} ROOTS\n${top(byRoot, 45)}`);
  console.log(`[census] ${name} MATS\n${top(byMat, 45)}`);
  if (detail) console.log(`[census] ${name} OBJS\n${top(byObj, 80)}`);
};
